-- Add Core Keywords to company_profiles: exactly 5 SEO pillar keywords per company,
-- used by the Topic Generator tool as the "core" terms long-tail topics should support.

alter table company_profiles
  add column core_keywords jsonb not null default '[]'::jsonb;

comment on column company_profiles.core_keywords is
  'Exactly 5 high-volume/competitive SEO pillar keywords for this company, enforced in the UI. Long-tail article topics generated by the Topic Generator tool are meant to support these.';
